CREATE TABLE "blog_post" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "author_id" BIGINT NOT NULL,
    "title" VARCHAR(200) NOT NULL,
    "slug" VARCHAR(100) NOT NULL,
    "status" TEXT NOT NULL DEFAULT 'draft' CHECK ("status" IN ('draft', 'published')),
    "views" INTEGER NOT NULL DEFAULT 0,
    "likes" INTEGER NOT NULL DEFAULT 0,
    "score" DOUBLE PRECISION DEFAULT 1.5,
    "public" BOOLEAN NOT NULL DEFAULT true,
    "body" BYTEA NOT NULL,
    "published_at" TIMESTAMPTZ,
    CONSTRAINT "blog_post_slug_key" UNIQUE ("slug"),
    CONSTRAINT "blog_post_author_id_slug_key" UNIQUE ("author_id", "slug")
);

CREATE TABLE "people" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "name" TEXT NOT NULL,
    "parent_id" BIGINT,
    "editor_id" BIGINT NOT NULL,
    "reviewer_id" BIGINT,
    "code" TEXT NOT NULL,
    "order" INTEGER NOT NULL DEFAULT 7,
    "admin" BOOLEAN NOT NULL DEFAULT false,
    "created_at" TIMESTAMPTZ NOT NULL,
    "updated_at" TIMESTAMPTZ NOT NULL,
    CONSTRAINT "people_editor_id_key" UNIQUE ("editor_id"),
    CONSTRAINT "people_code_key" UNIQUE ("code")
);

ALTER TABLE "blog_post" ADD CONSTRAINT "blog_post_author_id_fkey" FOREIGN KEY ("author_id") REFERENCES "people" ("id") ON DELETE NO ACTION;

ALTER TABLE "people" ADD CONSTRAINT "people_parent_id_fkey" FOREIGN KEY ("parent_id") REFERENCES "people" ("id") ON DELETE NO ACTION;

ALTER TABLE "people" ADD CONSTRAINT "people_editor_id_fkey" FOREIGN KEY ("editor_id") REFERENCES "people" ("id") ON DELETE NO ACTION;

ALTER TABLE "people" ADD CONSTRAINT "people_reviewer_id_fkey" FOREIGN KEY ("reviewer_id") REFERENCES "people" ("id") ON DELETE NO ACTION;

CREATE INDEX "blog_post_status_idx" ON "blog_post" ("status");

CREATE INDEX "blog_post_author_id_idx" ON "blog_post" ("author_id");

CREATE INDEX "people_reviewer_id_idx" ON "people" ("reviewer_id");

CREATE INDEX "people_code_idx" ON "people" ("code");

CREATE INDEX "people_parent_id_idx" ON "people" ("parent_id");
